pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am, uint256 balance, uint256 unlockDelta) public {
        address actor = address(0x1000);
        uint256 min = c.MinSum();
        vm.assume(balance >= min);
        vm.assume(am > 0 && balance > 0);
        vm.assume(unlockDelta <= 365 days);
        uint256 unlockTime = block.timestamp + unlockDelta;

        vm.deal(actor, balance);
        vm.prank(actor);
        c.Put{value: balance}(unlockTime);

        vm.warp(block.timestamp + unlockDelta + 1);
        vm.deal(actor, 0);

        bool ok;
        try c.Collect(am) {
            ok = true;
        } catch {
            ok = false;
        }

        (uint256 finalUnlockTime, uint256 finalBalance) = c.Acc(actor);
        assertTrue(
            (am <= balance) ? (ok && finalBalance + am == balance) : !ok || finalBalance == balance || finalBalance + am == balance,
            "invariant broken: balance underflow or revert inconsistency"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 initialBalance, uint256 collectAmt) public {
        // Admissible domain: initial balance >= MinSum (1 ether) so Collect can enter the if-body
        vm.assume(initialBalance >= c.MinSum());
        // unlockTime must be in the past so block.timestamp > unlockTime holds after setup
        vm.assume(unlockTime < block.timestamp);
        // Amount to collect can be any, including larger than balance (fuzzer will find bug-triggering values)
        // We use a fresh address to avoid interference with test contract's own balance
        address actor = address(0x1234);
        vm.deal(actor, 100 ether);

        // Fund the account: Put initial balance into Acc[actor]
        vm.prank(actor);
        c.Put{value: initialBalance}(unlockTime);

        uint256 beforeBalance = c.Acc(actor).balance;

        // Attempt to collect; the call may revert (e.g. if _am > balance in reference version's subtraction),
        // but the buggy version may succeed in the external call while failing the subtraction inside the assembly.
        bool success;
        vm.prank(actor);
        try c.Collect(collectAmt) { success = true; } catch { success = false; }

        uint256 afterBalance = c.Acc(actor).balance;

        // Rule: If the Collect call succeeded (no revert), then the on-chain balance MUST have been reduced
        // by exactly collectAmt. The mutant violates this because it can succeed while leaving balance unchanged
        // when collectAmt > balance (the subtraction reverts inside the unused _d call data but the external
        // call to msg.sender succeeds and the function does not revert overall).
        assertTrue(!success || afterBalance == beforeBalance - collectAmt);
    }
}

