import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint48 warpTime) public {
        vm.assume(depositAmount >= 1 ether);
        vm.assume(collectAmount > 0);
        vm.assume(warpTime > 0);
        address actor = address(0x1234);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Put{value: depositAmount}(block.timestamp + warpTime);
        vm.warp(block.timestamp + warpTime + 1);
        uint256 balBefore = c.Acc(actor);
        bool ok = true;
        vm.prank(actor);
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }
        if (ok) {
            assertTrue(collectAmount <= balBefore);
        } else {
            assertTrue(true);
        }
    }
}

