pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _am, uint256 _deposit, uint256 _unlockTime) public {
        // Bound _deposit to avoid overflow in add_uint256
        _deposit = bound(_deposit, 0, type(uint256).max / 2);
        // Bound _am to be at most _deposit + some extra to explore underflow scenarios
        _am = bound(_am, 0, _deposit + 1 ether);
        // Unlock time: allow past and future
        _unlockTime = bound(_unlockTime, 0, type(uint256).max);

        // Setup: user deposits
        address user = address(0x1234);
        vm.deal(user, _deposit);
        vm.prank(user);
        c.Put{value: _deposit}(_unlockTime);

        // Warp past unlock time to meet condition
        uint256 warpTime = _unlockTime > block.timestamp ? _unlockTime + 1 : block.timestamp + 1;
        vm.warp(warpTime);

        // Record balance before Collect
        uint256 beforeBal = c.Acc(user).balance;

        // Try Collect with _am (which may exceed balance)
        vm.prank(user);
        bool ok;
        try c.Collect(_am) {
            ok = true;
        } catch {
            ok = false;
        }

        // After attempt, check invariants
        uint256 afterBal = c.Acc(user).balance;

        // General rule: If Collect succeeded, after balance must be >= 0 (always true for correct contract)
        // Bug: when _am > balance, sub_uint256 underflows reverts, but mutant skips check and call may succeed,
        // leading to no balance deduction (or underflow revert) – this assertion catches inconsistency.
        assertTrue(!ok || afterBal <= beforeBal);
    }
}
